-- 通电的一瞬间, 开启自己关联的 RoomActivator
-- 并且切换 门上的 视觉效果
    

---@class OpenRoomActivator
---@field roomActivatorBH     Engine.Modules.LuaBehaviour
---@field doorStateHandleBH     Engine.Modules.LuaBehaviour
local OpenRoomActivator = Class('OpenRoomActivator')



-- ========================================================

--- lua:
local cs_coroutine = require 'XLua.cs_coroutine' -- 协程
local Yielders = CS.Engine.Lib.Yielders -- 协程


local QuestUtils = import('Game.DreamSpace.Quest.QuestUtils')
---@type LuaParametersReader
local LuaParametersReader = import('Game.Utils.LuaParametersReader')

local DreamSpaceLuaUtils = import('Game.DreamSpace.Tools.DreamSpaceLuaUtils')
---:
local Object = CS.UnityEngine.Object
local GameObject = CS.UnityEngine.GameObject
local Canvas = CS.UnityEngine.Canvas
local Transform = CS.UnityEngine.Transform
local Button = CS.UnityEngine.UI.Button
local RectTransform = CS.UnityEngine.RectTransform
local Vector3 = CS.UnityEngine.Vector3
local Quaternion = CS.UnityEngine.Quaternion
local Color = CS.UnityEngine.Color
local Time = CS.UnityEngine.Time
local Text = CS.UnityEngine.UI.Text
local Image = CS.UnityEngine.UI.Image
local Animation = CS.UnityEngine.Animation
local Animator = CS.UnityEngine.Animator


--- funtoy:
local BehaviourAction = CS.Engine.Lib.BehaviourAction
local KTool = CS.Engine.Lib.KTool
local LuaParameters = CS.Engine.Modules.LuaParameters

local ElectricalTrigger = CS.ElectricalSystem.ElectricalTrigger
local Interrupter = CS.ElectricalSystem.ElectricalSwitch.Interrupter
local OnOff = CS.Game.OnOff

local ElectricalApplianceBase = CS.ElectricalSystem.ElectricalApplianceBase



-- ========================================================


local State = 
{
    Off = 0,  
    On  = 1,   
}


-- ========================================================

function OpenRoomActivator:__init()
    self.controller = nil
end


function OpenRoomActivator:__delete()
end


function OpenRoomActivator:Start()
    KTool.SetActive(self.controller.gameObject, true)

    -- 允许为空, 比如那些未被使用的门
    if isNull(self.roomActivatorBH) then 
        return
    end 

    self.roomActivator = DreamSpaceLuaUtils.GetLuaScr(self.roomActivatorBH.gameObject, "Game.DreamSpace.Performance.RoomActivator.RoomActivator" )
    assert( self.roomActivator )

    assert( self.doorStateHandleBH )
    self.doorStateHandle = DreamSpaceLuaUtils.GetLuaScr(self.doorStateHandleBH.gameObject, "Game.DreamSpace.ElectricalSystem.Appliance.DoorStateHandle" )
    assert( self.doorStateHandle )

    self.state = State.Off   

    self.eBase = KTool.GetComponent(self.controller.gameObject, typeof(ElectricalApplianceBase))
    self.eBase:OnHandleElectrifiedState( '+', function( brain_ ) 
        
        if ( self.state == State.Off ) then
            self.state = State.On
            self.roomActivator.isDoorMotionActive = true

            self.doorStateHandle:ToWalkable()
        end
    end )    
end




function OpenRoomActivator:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end

-- =========================================== Self ================================================ --




return OpenRoomActivator

